import React from 'react';

/** Props for the {@link Tooltip} component. */
export interface TooltipProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Text displayed inside the tooltip. */
  text: string;
  /** Additional CSS class names on the wrapper. */
  className?: string;
  /** The element that triggers the tooltip on hover/focus. */
  children: React.ReactNode;
}

/**
 * Hover info tooltip with dither styling.
 * Wraps children in a `sk-tooltip-wrapper` and positions a `sk-tooltip` above them.
 */
export const Tooltip = React.forwardRef<HTMLDivElement, TooltipProps>(
  ({ text, className, children, ...rest }, ref) => (
    <div ref={ref} className={`sk-tooltip-wrapper${className ? ` ${className}` : ''}`} {...rest}>
      {children}
      <span className="sk-tooltip" role="tooltip">{text}</span>
    </div>
  ),
);

Tooltip.displayName = 'Tooltip';

/**
 * skeehn — Tooltip Component
 *
 * @component sk-tooltip-wrapper > .sk-tooltip
 * @variants  default | [data-variant="pixel"] | [data-variant="retro"] | [data-variant="ascii"]
 * @states    :hover | :focus-within (triggers visibility)
 * @a11y      role="tooltip", focus-within support, pointer-events none
 * @print     Hidden
 */

.sk-tooltip-wrapper { position: relative; display: inline-flex; }
.sk-tooltip { position: absolute; bottom: calc(100% + var(--sk-space-1)); left: 50%; transform: translateX(-50%); padding: var(--sk-space-1) var(--sk-space-2); font-family: var(--sk-font-mono); font-size: var(--sk-font-size-xs); color: hsl(var(--sk-background)); background: hsl(var(--sk-foreground)); border-radius: var(--sk-radius); white-space: nowrap; opacity: 0; visibility: hidden; transition: all var(--sk-transition-fast); z-index: var(--sk-z-tooltip); pointer-events: none; letter-spacing: 0.02em; }
.sk-tooltip::after { content: ""; position: absolute; top: 100%; left: 50%; transform: translateX(-50%); border: 4px solid transparent; border-top-color: hsl(var(--sk-foreground)); }
.sk-tooltip-wrapper:hover .sk-tooltip, .sk-tooltip-wrapper:focus-within .sk-tooltip { opacity: 1; visibility: visible; transform: translateX(-50%) translateY(-2px); }

/* Micro-interaction — slide-up entrance */
.sk-tooltip { transform: translateX(-50%) translateY(4px); }

/* Pixel variant */
.sk-tooltip[data-variant="pixel"] { background: hsl(var(--sk-foreground)); border: 2px solid hsl(var(--sk-foreground)); box-shadow: 2px 2px 0 hsl(var(--sk-foreground) / 0.5); border-radius: 0; }
.sk-tooltip[data-variant="pixel"]::after { border-top-color: hsl(var(--sk-foreground)); }

/* Retro variant */
.sk-tooltip[data-variant="retro"] { background: hsl(var(--sk-foreground)); text-shadow: 0 0 3px hsl(var(--sk-background) / 0.3); box-shadow: 0 0 6px hsl(var(--sk-foreground) / 0.2); }

/* ASCII variant */
.sk-tooltip[data-variant="ascii"] { background: hsl(var(--sk-background)); color: hsl(var(--sk-foreground)); border: 1px dashed hsl(var(--sk-border-color)); }
.sk-tooltip[data-variant="ascii"]::after { display: none; }

/* Skeleton */
.sk-tooltip[data-skeleton] { display: none; }

@media print {
  .sk-tooltip { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .sk-tooltip { transition: opacity var(--sk-transition-fast); transform: translateX(-50%); }
  .sk-tooltip-wrapper:hover .sk-tooltip,
  .sk-tooltip-wrapper:focus-within .sk-tooltip { transform: translateX(-50%); }
}
